### 3. Update `lib/payments/process-stripe-event.ts` — add `invoice.payment_succeeded` + `invoice.finalized` handlers

Add two new event types to the switch in `processStripeEvent`:

```ts
case 'invoice.finalized':
  await handleInvoiceFinalized(event.data.object as StripeInvoiceShape, supabase);
  break;

case 'invoice.payment_succeeded':
  await handleInvoicePaymentSucceeded(event.data.object as StripeInvoiceShape, supabase);
  break;
```

Define `StripeInvoiceShape` interface with the fields needed (mirrors S14 pattern):

```ts
interface StripeInvoiceShape {
  id: string;
  status: string;
  total: number;
  subtotal: number;
  tax: number | null;
  amount_paid: number;
  amount_due: number;
  payment_intent: string | { id: string } | null;
  customer: string;
  currency: string;
  automatic_tax?: { status?: string | null } | null;
  metadata?: Record<string, string | undefined> | null;
  status_transitions?: { finalized_at?: number | null; paid_at?: number | null } | null;
}
```

Define handlers:

```ts
async function handleInvoiceFinalized(invoice: StripeInvoiceShape, supabase: SupabaseServiceClient): Promise<void> {
  const piId = typeof invoice.payment_intent === 'string'
    ? invoice.payment_intent
    : invoice.payment_intent?.id ?? null;
  const finalizedAt = invoice.status_transitions?.finalized_at
    ? new Date(invoice.status_transitions.finalized_at * 1000).toISOString()
    : null;

  const { error } = await supabase.rpc(RPC.STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_invoice_id: invoice.id,
    p_status: invoice.status,
    p_payment_intent_id: piId,
    p_amount_paid_cents: invoice.amount_paid,
    p_finalized_at: finalizedAt,
    p_paid_at: null,
  });
  if (error) {
    logger.error({ invoice_id: invoice.id, err: error }, 'invoice.finalized webhook update failed');
    throw error;
  }
}

async function handleInvoicePaymentSucceeded(invoice: StripeInvoiceShape, supabase: SupabaseServiceClient): Promise<void> {
  const piId = typeof invoice.payment_intent === 'string'
    ? invoice.payment_intent
    : invoice.payment_intent?.id ?? null;
  const paidAt = invoice.status_transitions?.paid_at
    ? new Date(invoice.status_transitions.paid_at * 1000).toISOString()
    : null;

  const { error } = await supabase.rpc(RPC.STRIPE_INVOICE_UPDATE_STATUS_FROM_WEBHOOK, {
    p_invoice_id: invoice.id,
    p_status: 'paid',
    p_payment_intent_id: piId,
    p_amount_paid_cents: invoice.amount_paid,
    p_finalized_at: null,
    p_paid_at: paidAt,
  });
  if (error) {
    logger.error({ invoice_id: invoice.id, err: error }, 'invoice.payment_succeeded webhook update failed');
    throw error;
  }

  // Note: tax mirror for invoice-backed flow happens via the existing payment_intent.succeeded
  // handler since invoice.payment_succeeded fires AFTER the underlying PI succeeds.
  // The PI's amount_details.tax_breakdown is now authoritative because automatic_tax was
  // enabled on the invoice.
}
```

